import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 10.5, D: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { server.close() }
}

async function totalFor(items) {
  return withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    const order = await res.json()
    const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
    assert.equal(fetched.total, order.total)
    return order.total
  })
}

// Characterization tests: these pin CURRENT behaviour, including suspected bugs (marked).
test('small order has no discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
})

test('multiple line items are summed', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 70)
})

test('exactly 100 gets no discount (threshold is strictly > 100)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('just over 100 gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)
})

test('large order gets flat 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 40 }]), 900)
})

test('discount applies to the whole order, not tiered', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 100 }]), 2250)
})

// SUSPECT: total is floored to whole euros, so cents are dropped (101 -> 90.9 -> 90).
test('SUSPECT: discounted total is truncated to whole euros', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }, { sku: 'A', qty: 0.1 }]), 90)
})

// SUSPECT: undiscounted totals are floored too (10.5 -> 10).
test('SUSPECT: fractional prices lose cents even without discount', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 1 }]), 10)
})

// SUSPECT: float error plus floor (33.33 * 3 = 99.99 -> 99).
test('SUSPECT: decimal prices are floored', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 3 }]), 99)
})

test('rejects empty items', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: '{"items":[]}' })
    assert.equal(res.status, 400)
  })
})
EOF
